def geometry(self, *, kind: str, relative_to: str = "screen", to96dpi: bool = True, pt: str = "cc") -> dict[str, Any]:
    result = self._session._run_web_value("web.get_geometry", self.id, kind=kind,
        relative_to=relative_to, to96dpi=to96dpi, pt=pt, timeout_ms=5000)
    value = result.get("rect" if kind == "bounding" else "point")
    if kind == "bounding":
        valid = isinstance(value, dict) and all(
            isinstance(value.get(key), int) and not isinstance(value[key], bool)
            for key in ("x", "y", "width", "height")
        )
    else:
        valid = isinstance(value, list) and len(value) == 2 and all(
            isinstance(v, int) and not isinstance(v, bool) for v in value
        )
    if not valid:
        raise RpcProtocolError("Runtime 返回的网页元素坐标无效", method="web.get_geometry", response=result)
    return result

def _web_physical_geometry(self, desc: dict[str, Any], timeout_ms: int, *, read_geometry: bool = True) -> dict[str, Any]:
    from runtime.services.uiautomation_provider import get_uiautomation_provider
    provider = self.uia_provider or get_uiautomation_provider()
    raw = provider.request("web.resolve_element", {
        "element_ref": desc["element_ref"], "targetSessionId": desc["target_session_id"],
        "targetTabId": desc["target_tab_id"], "read_geometry": read_geometry,
        "browserExeName": "msedge.exe" if desc["target_browser"] == "edge" else "chrome.exe",
        "timeout_ms": timeout_ms,
    }, timeout_ms=timeout_ms)
    if self.web_page_state.resolve_page(desc["page_ref"]) is None:
        return business_error(3, "stale_page_reference", message="网页对象已失效")
    return _public_web_bridge_payload(raw, desc)

def web_get_geometry(self, params: dict[str, Any]) -> dict[str, Any]:
    ctx, err = self._resolve_web_ctx(params)
    if err is not None:
        return err
    assert ctx is not None
    if ctx.get("locator_kind") != "runtime_ref":
        return business_error(2, "invalid_params", message="请先查找当前网页元素")
    desc, err = self._web_descriptor(ctx)
    if err is not None:
        return err
    kind = params.get("kind", "bounding")
    relative = params.get("relative_to", "screen")
    if kind not in {"bounding", "anchor", "viewport_anchor"} or relative not in {"screen", "window"}:
        return business_error(2, "invalid_params", message="坐标类型无效")
    timeout_ms = _int_param(params.get("timeout_ms"), 5000)
    try:
        if kind == "viewport_anchor":
            raw = self.web_bridge.action("geometry", **self._web_selector_params(desc),
                **self._web_command_target(params, desc), timeout_ms=timeout_ms)
        else:
            raw = self._web_physical_geometry(desc, timeout_ms)
        if _web_bridge_error(raw):
            return _public_web_bridge_payload(raw, desc)
        physical = raw["screen_rect"]
        if kind == "viewport_anchor":
            if physical.get("client_rect_space") != "top_viewport_css":
                raise ValueError("viewport geometry missing")
            rect = dict(physical["client_rect"])
            factor = 1.0
        else:
            if physical.get("coordinate_space") != "screen_physical":
                raise ValueError("physical geometry missing")
            if physical.get("client_rect_space") != "top_viewport_css":
                raise ValueError("viewport geometry missing")
            css = physical["client_rect"]
            scale = float(raw["css_scale"])
            if not math.isfinite(scale) or scale <= 0:
                raise ValueError("viewport scale missing")
            rect = {key: math.floor(float(css[key]) * scale + 0.5) for key in ("x", "y", "w", "h")}
            rect["x"] += raw["viewport_origin"]["x"]
            rect["y"] += raw["viewport_origin"]["y"]
            if relative == "window":
                rect["x"] -= raw["window_client_origin"]["x"]
                rect["y"] -= raw["window_client_origin"]["y"]
            dpi = float(raw["window_dpi"])
            if not math.isfinite(dpi) or dpi <= 0:
                raise ValueError("window dpi missing")
            factor = 96.0 / dpi if params.get("to96dpi", True) else 1.0
        if not all(math.isfinite(float(rect[key])) for key in ("x", "y", "w", "h")):
            raise ValueError("invalid rectangle")
        if kind != "bounding":
            x, y = point_in_rect_xywh(rect, str(params.get("pt") or "cc"), inset=0)
            return {"error": 0, "point": [math.floor(x * factor + 0.5), math.floor(y * factor + 0.5)]}
        x, y, width, height = (math.floor(rect[key] * factor + 0.5) for key in ("x", "y", "w", "h"))
        return {"error": 0, "rect": {"x": x, "y": y, "width": width, "height": height}}
    except (KeyError, TypeError, ValueError):
        return business_error(5, "browser_viewport_conversion_failed", message="无法获取网页元素坐标")
    except Exception as exc:
        return business_error(5, "web_bridge_unavailable", message=_public_web_bridge_message(exc, desc))

fn resolve_web_element_with_activation(
    params: Value,
    web_probe: &mut dyn WebProbeClient,
    activate: impl FnOnce(isize) -> bool,
) -> Value {
    let started = Instant::now();
    let failure = |trace: &str| web_validation_failure(5, trace, "无法定位网页元素", None);
    if !params.get("element_ref").is_some_and(Value::is_object)
        || !params
            .get("targetTabId")
            .and_then(Value::as_u64)
            .is_some_and(|id| id > 0)
        || !params
            .get("targetSessionId")
            .and_then(Value::as_str)
            .is_some_and(|id| !id.trim().is_empty())
    {
        return failure("invalid_params");
    }
    let timeout_ms = params
        .get("timeout_ms")
        .and_then(Value::as_u64)
        .unwrap_or(5000)
        .clamp(1, 60000);
    let read_geometry = params.get("read_geometry").and_then(Value::as_bool) == Some(true);
    let mut command = params;
    command["rootHwnd"] = json!(0);
    command["rootPid"] = json!(0);
    command["captureSessionId"] = json!(capture_session_id(None));
    command["action"] = json!(if read_geometry { "geometry" } else { "locate" });
    command["scrollIntoView"] = json!(!read_geometry);
    command["timeoutMs"] = json!(timeout_ms);
    let result = match execute_web_validation_probe(web_probe, &command, timeout_ms) {
        Ok(result) => result,
        Err(_) => return failure("web_bridge_unavailable"),
    };
    if value_as_i64(result.get("error")).unwrap_or(5) != 0 {
        return result;
    }
    let Some(root_hwnd) = result
        .get("provider_root_hwnd")
        .and_then(Value::as_i64)
        .filter(|hwnd| *hwnd > 0)
    else {
        return failure("browser_host_window_mismatch");
    };
    if !read_geometry && !activate(root_hwnd as isize) {
        return web_validation_failure(
            5,
            "browser_window_activation_failed",
            "无法激活浏览器窗口，已取消操作",
            None,
        );
    }
    let remaining = Duration::from_millis(timeout_ms)
        .saturating_sub(started.elapsed()).as_millis() as u64;
    let (mut result, geometry) = match execute_web_validation_with_viewport(
        web_probe, &command, remaining, Some(result),
        |evidence| resolve_browser_viewport_geometry(root_hwnd as HWND, evidence),
    ) {
        Ok(result) => result,
        Err(WebValidationAttemptError::Probe(_)) => return failure("web_bridge_unavailable"),
        Err(WebValidationAttemptError::Viewport(trace)) => return failure(trace),
    };
    if value_as_i64(result.get("error")).unwrap_or(5) != 0 {
        return result;
    }
    if result.get("provider_root_hwnd").and_then(Value::as_i64) != Some(root_hwnd) {
        return failure("browser_host_window_mismatch");
    }
    let Some(geometry) = geometry else {
        return failure("browser_viewport_evidence_missing");
    };
    let Some(evidence) = first_web_validation_evidence(&result) else {
        return failure("web_viewport_evidence_missing");
    };
    if convert_web_validation_result_to_screen(&mut result, geometry) == 0 {
        return failure("browser_viewport_conversion_failed");
    }
    let mut response = json!({"error": 0, "ok": true, "found": true, "count": 1,
        "screen_rect": result["screen_rect"], "strategy": "provider_web_dom"});
    if read_geometry {
        let dpi = unsafe { windows_sys::Win32::UI::HiDpi::GetDpiForWindow(root_hwnd as HWND) };
        let mut client_origin = POINT { x: 0, y: 0 };
        if dpi == 0 || unsafe { ClientToScreen(root_hwnd as HWND, &mut client_origin) } == 0 {
            return failure("browser_viewport_conversion_failed");
        }
        response["window_dpi"] = json!(dpi);
        response["window_client_origin"] = json!({"x": client_origin.x, "y": client_origin.y});
        response["viewport_origin"] = json!({"x": geometry.origin.0, "y": geometry.origin.1});
        response["css_scale"] = json!(evidence.scale);
    }
    response
